import { createWindowConfCopy, IPermissionAskResult, Manifest, permissionUtils, WebViewJs, WindowConf } from '@droid/android';
import toast from 'react-hot-toast';
import { ulid } from 'ulid';

export function openFloatWindow(windowConf:WindowConf) {
  const url = windowConf.htmlConf?.url || 'about:blank';
  const windowId = windowConf.windowId || `float-window-${ulid()}`;
  checkPermission();
  function createCopy(url: string, windowId: string, callbackEventType: string) {
    // let windowConf:WindowConf = {
    //   htmlConf: {
    //     url: `${url}`,
    //   },
    //   windowId,
    //   floatWindowConf:{
    //     floatConf:{
    //         tag:windowId
    //     },
    //     // exitByLongTouch:1000 * 5
    //     foregroundText:"点击关闭浮窗时钟"
    //   }
    // };
    return createWindowConfCopy(windowConf);
  }

  function onAskPermissionComplete(stoped: boolean, granted: boolean, result?: IPermissionAskResult) {
    if (!granted) {
      toast.error('有未授权的权限，所以无法运行。\n请再次点击按钮运行授权并同意赋权后才能继续执行操作。');
      return;
    }

    const eventType = ulid(); // "a11yNodeSelectActionItem";
    // openHtmlShowA11yNodeInfoWindow(eventType, windowId);
    // windowConf.htmlConf?.webViewJsParams?.javaToJsDataString = JSON.stringify({ event: eventType });
    // const conf = createCopy(url, windowId, eventType);
    const confString = JSON.stringify(windowConf);
    console.log('openFloatWindow: created window conf string:', confString);
    WebViewJs.instance.createWindow(confString);
  }
  function checkPermission() {
    const eventType = ulid(); // "a11yNodeSelectActionItem";
    const windowId = ulid();
    const res = permissionUtils.askPermissions(
      [Manifest.Permission.SYSTEM_ALERT_WINDOW],
      eventType,
      onAskPermissionComplete,
    );
    if (res.isGranted) {
      onAskPermissionComplete(false, true);
    }
  }
}
